package com.sudoplatform.sudoprivacyinteraction.internal.domain.entities.dataHolder

/**
 * Input for [DataHolderService.list].
 *
 * @property virtualPresenceId [String] The identifier of the virtual presence to list data
 *  holders for.
 * @property limit [Int] Number of records to return.
 * @property nextToken [String] A token generated by a previous call to allow for pagination.
 */
internal data class ListDataHoldersInput(
    val virtualPresenceId: String,
    val limit: Int? = null,
    val nextToken: String? = null,
)

/**
 * Output for [DataHolderService.list].
 *
 * @property items [List] The list of data holders retrieved in this query.
 * @property nextToken [String] A token generated by a previous call to allow for pagination.
 */
internal data class ListDataHoldersOutput(
    val items: List<DataHolderEntity>,
    val nextToken: String? = null,
)

/**
 * Input for [DataHolderService.listScanSummaries].
 *
 * @property dataHolderId [String] The identifier of the data holder to list scan summaries for.
 * @property limit [Int] Number of records to return.
 * @property nextToken [String] A token generated by a previous call to allow for pagination.
 */
internal data class ListDataHolderScanSummariesInput(
    val dataHolderId: String,
    val limit: Int? = null,
    val nextToken: String? = null,
)

/**
 * Output for [DataHolderService.listScanSummaries].
 *
 * @property items [List] The list of scan summaries retrieved in this query.
 * @property nextToken [String] A token generated by a previous call to allow for pagination.
 */
internal data class ListDataHolderScanSummariesOutput(
    val items: List<DataHolderScanSummaryEntity>,
    val nextToken: String? = null,
)

/**
 * Core entity representation of a data holder service used in business logic.
 * Used to perform operations for data holders.
 */
internal interface DataHolderService {
    /**
     * Retrieve a single data holder by ID.
     *
     * @param id [String] The unique identifier of the data holder.
     * @return The [DataHolderEntity], or `null` if not found.
     */
    suspend fun get(id: String): DataHolderEntity?

    /**
     * Retrieve a list of data holders associated with a virtual presence.
     *
     * @param input [ListDataHoldersInput] Parameters used to list data holders.
     * @return A [ListDataHoldersOutput] of data holders matching the search criteria.
     */
    suspend fun list(input: ListDataHoldersInput): ListDataHoldersOutput

    /**
     * Retrieve a list of scan summaries associated with a data holder, most recent first.
     *
     * @param input [ListDataHolderScanSummariesInput] Parameters used to list scan summaries.
     * @return A [ListDataHolderScanSummariesOutput] of scan summaries matching the search criteria.
     */
    suspend fun listScanSummaries(input: ListDataHolderScanSummariesInput): ListDataHolderScanSummariesOutput
}
